#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int u, v, w;
} Edge;

static int compare_edges(const void *a, const void *b) {
    const Edge *x = (const Edge *)a;
    const Edge *y = (const Edge *)b;
    return (y->w > x->w) - (y->w < x->w);
}

static int find_root(int *parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main(void) {
    int n, b;
    if (scanf("%d %d", &n, &b) != 2) return 0;

    Edge *edges = malloc((size_t)b * sizeof(Edge));
    for (int i = 0; i < b; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    int *parent = malloc((size_t)(n + 1) * sizeof(int));
    int *size = malloc((size_t)(n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    int *head = malloc((size_t)(n + 1) * sizeof(int));
    for (int i = 0; i <= n; i++) head[i] = -1;

    int max_tree_edges = 2 * (n - 1);
    int *to = malloc((size_t)max_tree_edges * sizeof(int));
    int *weight = malloc((size_t)max_tree_edges * sizeof(int));
    int *next = malloc((size_t)max_tree_edges * sizeof(int));
    int edge_count = 0;

    qsort(edges, (size_t)b, sizeof(Edge), compare_edges);

    for (int i = 0; i < b; i++) {
        int ru = find_root(parent, edges[i].u);
        int rv = find_root(parent, edges[i].v);
        if (ru == rv) continue;

        if (size[ru] < size[rv]) {
            int tmp = ru;
            ru = rv;
            rv = tmp;
        }
        parent[rv] = ru;
        size[ru] += size[rv];

        int u = edges[i].u, v = edges[i].v, w = edges[i].w;
        to[edge_count] = v;
        weight[edge_count] = w;
        next[edge_count] = head[u];
        head[u] = edge_count++;

        to[edge_count] = u;
        weight[edge_count] = w;
        next[edge_count] = head[v];
        head[v] = edge_count++;
    }

    int log = 1;
    while ((1 << log) <= n) log++;

    size_t stride = (size_t)n + 1;
    int *up = malloc((size_t)log * stride * sizeof(int));
    int *mn = malloc((size_t)log * stride * sizeof(int));

    int *depth = malloc((size_t)(n + 1) * sizeof(int));
    int *queue = malloc((size_t)(n + 1) * sizeof(int));
    char *visited = calloc((size_t)(n + 1), sizeof(char));

    int front = 0, back = 0;
    queue[back++] = 1;
    visited[1] = 1;
    depth[1] = 0;
    up[1] = 0;
    mn[1] = INT_MAX;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (visited[v]) continue;
            visited[v] = 1;
            depth[v] = depth[u] + 1;
            up[v] = u;
            mn[v] = weight[e];
            queue[back++] = v;
        }
    }

    for (int k = 1; k < log; k++) {
        size_t prev = (size_t)(k - 1) * stride;
        size_t curr = (size_t)k * stride;
        for (int v = 0; v <= n; v++) {
            int p = up[prev + v];
            up[curr + v] = up[prev + p];
            int a = mn[prev + v];
            int c = mn[prev + p];
            mn[curr + v] = a < c ? a : c;
        }
    }

    int queries;
    scanf("%d", &queries);
    while (queries--) {
        int x, y;
        scanf("%d %d", &x, &y);

        int answer = INT_MAX;
        if (depth[x] < depth[y]) {
            int tmp = x;
            x = y;
            y = tmp;
        }

        int diff = depth[x] - depth[y];
        for (int k = 0; k < log; k++) {
            if (diff & (1 << k)) {
                int idx = (int)((size_t)k * stride + x);
                if (mn[idx] < answer) answer = mn[idx];
                x = up[idx];
            }
        }

        if (x != y) {
            for (int k = log - 1; k >= 0; k--) {
                int ix = (int)((size_t)k * stride + x);
                int iy = (int)((size_t)k * stride + y);
                if (up[ix] != up[iy]) {
                    if (mn[ix] < answer) answer = mn[ix];
                    if (mn[iy] < answer) answer = mn[iy];
                    x = up[ix];
                    y = up[iy];
                }
            }
            int ix = x;
            int iy = y;
            if (mn[ix] < answer) answer = mn[ix];
            if (mn[iy] < answer) answer = mn[iy];
        }

        printf("%d\n", answer);
    }

    free(edges);
    free(parent);
    free(size);
    free(head);
    free(to);
    free(weight);
    free(next);
    free(up);
    free(mn);
    free(depth);
    free(queue);
    free(visited);
    return 0;
